#!/usr/bin/env bash
# Watches PyPI for google-antigravity releases past the pinned harness.
#
# The bridge drives one harness revision (SUPPORTED_HARNESS_VERSION in
# src/antigravity/config.rs), and nothing else notices a new one: the drift
# guard and the harness suites run against whatever CI installs, which is the
# pin (#499). When PyPI's latest differs from the pin, this diffs the two
# wheels' protobuf descriptors (.github/scripts/dump_harness_descriptor.py)
# and their Python SDK options (.github/scripts/dump_sdk_options.py, the
# parity table's keys), and opens or updates one rolling issue, the way
# report_scheduled_failure.sh keeps one per failing workflow. Once the pin
# catches up, the next run closes it.
#
# Usage: antigravity_release_watch.sh
# Requires: GH_TOKEN with issues:write; python3 with pip, unzip, jq.
# Test overrides: PINNED_VERSION, LATEST_VERSION, PINNED_WHEEL_DIR and
# LATEST_WHEEL_DIR (an unpacked wheel each) skip the source file, PyPI and
# the downloads.

set -euo pipefail
# A failed download inside `$(unpacked_wheel ..)` must stop the run, not hand
# an empty directory to the dump. (bash 4.4+; on older shells the dump still
# fails on the empty directory, one step later.)
shopt -s inherit_errexit 2>/dev/null || true

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ROOT="$(cd "$HERE/../.." && pwd)"

# Exported: `$ENV.TITLE` in the `--jq` filters reads the `gh` environment. A
# fixed title (the version lives in the body) keeps the lookup exact, so a
# daily run updates one issue instead of filing one per release.
export TITLE="Antigravity release watch: PyPI's google-antigravity differs from the pinned harness"
LABEL="antigravity-release"
EDIT_MARKER="<!-- Generated above; anything you add below this line is preserved. -->"

PINNED="${PINNED_VERSION:-$(sed -n 's/^pub const SUPPORTED_HARNESS_VERSION: &str = "\(.*\)";$/\1/p' \
  "$ROOT/src/antigravity/config.rs")}"
if [ -z "$PINNED" ]; then
  echo "::error::SUPPORTED_HARNESS_VERSION not found in src/antigravity/config.rs"
  exit 1
fi

# `timeout=`: without it a stalled pypi.org connection blocks until the job's
# own limit instead of failing fast (see api-surface-sweep.yml).
LATEST="${LATEST_VERSION:-$(python3 -I -c "
import json, urllib.request
with urllib.request.urlopen('https://pypi.org/pypi/google-antigravity/json', timeout=30) as r:
    print(json.load(r)['info']['version'])
")}"
echo "Pinned: $PINNED. Latest on PyPI: $LATEST."

existing_issue() {
  gh issue list --label "$LABEL" --state "$1" --limit 100 --json number,title \
    --jq '[.[] | select(.title == $ENV.TITLE) | .number] | first // empty'
}

if [ "$PINNED" = "$LATEST" ]; then
  OPEN=$(existing_issue open)
  if [ -z "$OPEN" ]; then
    echo "The pin is current; nothing to report."
    exit 0
  fi
  gh issue comment "$OPEN" --body "The pin is now google-antigravity $LATEST, the latest release. Closing.

---
_Generated by [Claude Code](https://claude.ai/code)_"
  gh issue close "$OPEN" --reason completed
  echo "Closed issue #$OPEN"
  exit 0
fi

WORK="$(mktemp -d)"
trap 'rm -rf "$WORK"' EXIT

# An unpacked wheel for `version`, in a directory of its own. The wheel is
# data: `--only-binary=:all:` means no sdist build runs, and the dump below
# reads it without importing anything from it.
unpacked_wheel() {
  local version="$1" dir="$WORK/wheel-$1"
  mkdir -p "$dir/dl"
  python3 -m pip download "google-antigravity==$version" --no-deps --only-binary=:all: -q \
    -d "$dir/dl" >&2
  unzip -q "$dir"/dl/*.whl -d "$dir/x" >&2
  echo "$dir/x"
}

PINNED_DIR="${PINNED_WHEEL_DIR:-$(unpacked_wheel "$PINNED")}"
LATEST_DIR="${LATEST_WHEEL_DIR:-$(unpacked_wheel "$LATEST")}"

python3 -I "$HERE/dump_harness_descriptor.py" "$PINNED_DIR" > "$WORK/pinned.descriptor"
python3 -I "$HERE/dump_harness_descriptor.py" "$LATEST_DIR" > "$WORK/latest.descriptor"
# diff exits 1 for "differences found" and 2 for trouble; only 2 may fail.
diff "$WORK/pinned.descriptor" "$WORK/latest.descriptor" > "$WORK/descriptor.diff" || [ $? -eq 1 ]

# The Python SDK's options: the keys of the parity table in
# docs/ANTIGRAVITY_BRIDGE_DESIGN.md. New Python-side options change no
# descriptor, so only this shows them before the pin moves. The pin's dump
# must be clean (the parity guard holds the table to it); the latest's may
# hold names the dump does not place yet, which --lenient lists on stderr
# instead of failing.
python3 -I "$HERE/dump_sdk_options.py" "$PINNED_DIR" > "$WORK/pinned.options"
python3 -I "$HERE/dump_sdk_options.py" --lenient "$LATEST_DIR" \
  > "$WORK/latest.options" 2> "$WORK/latest.problems"
diff "$WORK/pinned.options" "$WORK/latest.options" > "$WORK/options.diff" || [ $? -eq 1 ]

# Where the Python SDK chooses its transport. The #494 decision (D-018) is
# revisited once the SDK makes the Interactions-mode transport
# (use_interactions_api) its default.
grep -rn --include='*.py' 'use_interactions_api' "$LATEST_DIR/google/antigravity" 2>/dev/null \
  | grep -v -e '_test\.py:' -e '_pb2\.py:' | sed "s|$LATEST_DIR/||" | cut -c1-200 | head -20 \
  > "$WORK/transport.txt" || true

EXISTING=$(existing_issue all)
PREV_BODY=""
PREV_STATE=""
if [ -n "$EXISTING" ]; then
  # A plain assignment, not inside an `if`, so a failed read trips `set -e`.
  PREV=$(gh issue view "$EXISTING" --json state,body)
  PREV_STATE=$(jq -r .state <<<"$PREV")
  PREV_BODY=$(jq -r .body <<<"$PREV")
fi
PRESERVED=$(awk -v marker="$EDIT_MARKER" '
  { line = $0; sub(/\r$/, "", line) }
  found { print }
  line == marker { found = 1 }' <<<"$PREV_BODY")

BODY="$WORK/body.md"
{
  echo "\`google-antigravity\` **$LATEST** is on PyPI; this crate pins **$PINNED**"
  echo "(\`SUPPORTED_HARNESS_VERSION\` in \`src/antigravity/config.rs\`)."
  echo
  echo "The bridge speaks the harness's protocol directly, so a release can rename"
  echo "a value it matches on, add a config field the old harness rejects, or add"
  echo "a tool toggle that is on unless the bridge writes it off. None of that shows"
  echo "until the pin moves: CI installs the pin."
  echo
  echo "### Protocol descriptor diff"
  echo
  if [ -s "$WORK/descriptor.diff" ]; then
    echo "\`<\` only in $PINNED, \`>\` only in $LATEST: one line per message field and"
    echo "enum value of the wheels' \`_pb2\` modules."
    echo
    echo '<details><summary>Expand</summary>'
    echo
    # Tilde fence: the lines are upstream names, never backticks, but a
    # backtick fence would close early if that ever changed.
    echo '~~~diff'
    head -c 40000 "$WORK/descriptor.diff"
    if [ "$(wc -c < "$WORK/descriptor.diff")" -gt 40000 ]; then
      echo
      echo "... truncated; rerun .github/scripts/dump_harness_descriptor.py on both wheels ..."
    fi
    echo '~~~'
    echo
    echo '</details>'
  else
    echo "None: the two wheels' descriptors are identical. The release may still"
    echo "change behavior behind the same messages."
  fi
  echo
  echo "### Python SDK option diff"
  echo
  if [ -s "$WORK/options.diff" ]; then
    echo "\`<\` only in $PINNED, \`>\` only in $LATEST: the option keys"
    echo "\`.github/scripts/dump_sdk_options.py\` reads, which are the first column of"
    echo "the parity table in \`docs/ANTIGRAVITY_BRIDGE_DESIGN.md\`. Each new key needs"
    echo "a row there, modeled or with the reason it is not."
    echo
    echo '<details><summary>Expand</summary>'
    echo
    echo '~~~diff'
    head -c 20000 "$WORK/options.diff"
    if [ "$(wc -c < "$WORK/options.diff")" -gt 20000 ]; then
      echo
      echo "... truncated; rerun .github/scripts/dump_sdk_options.py on both wheels ..."
    fi
    echo '~~~'
    echo
    echo '</details>'
  else
    echo "None: both wheels expose the same option keys."
  fi
  if [ -s "$WORK/latest.problems" ]; then
    echo
    echo "$LATEST also exposes names the dump does not place yet (a new module,"
    echo "class or export). Read each into the script's \`SPEC\` or skip it there with"
    echo "the reason, then add its rows:"
    echo
    echo '~~~'
    head -c 10000 "$WORK/latest.problems"
    echo '~~~'
  fi
  echo
  echo "### Python transport (#494)"
  echo
  if [ -s "$WORK/transport.txt" ]; then
    echo "Where $LATEST's Python SDK sets \`use_interactions_api\`. If the default"
    echo "moved to the Interactions-mode transport, revisit the #494 decision."
    echo
    echo '~~~'
    cat "$WORK/transport.txt"
    echo '~~~'
  else
    echo "No \`use_interactions_api\` in $LATEST's Python sources: the transport"
    echo "selection moved or was removed. Revisit the #494 decision."
  fi
  echo
  echo "### Next steps"
  echo
  echo "1. Install $LATEST in a venv and run the harness suites with its \`bin\` first"
  echo "   on \`PATH\`: the key-free \`binary(antigravity_scripted)\`, then"
  echo "   \`binary(antigravity_harness)\` with a key (the drift guard reads the"
  echo "   wheel's protos)."
  echo "2. Model what changed: inbound values the drift guard names, outbound"
  echo "   config (a new \`HarnessSideTools\` toggle must be written explicitly), and"
  echo "   each new Python SDK option, which gets a row in the parity table"
  echo "   (\`test_python_sdk_options_are_all_in_the_parity_table\` in"
  echo "   \`binary(antigravity_scripted)\` fails until it has one)."
  echo "3. Bump the pin as CLAUDE.md describes (\`SUPPORTED_HARNESS_VERSION\`, every"
  echo "   pin and \"currently\" mention, and a row in the upgrade table in"
  echo "   \`docs/ANTIGRAVITY_BRIDGE_DESIGN.md\`). The next run of this watch then"
  echo "   closes this issue."
  echo
  echo "---"
  echo "_Generated by [Claude Code](https://claude.ai/code)_"
  echo
  # Which release this body describes; the comment below fires once per new
  # one. Above the edit marker, so the preserved section never carries it.
  echo "<!-- watch-latest: $LATEST -->"
  echo "$EDIT_MARKER"
  if [ -n "$PRESERVED" ]; then
    printf '%s\n' "$PRESERVED"
  fi
} > "$BODY"

if [ -z "$EXISTING" ]; then
  gh label create "$LABEL" \
    --description "A google-antigravity release differs from the pinned harness" \
    --color "5319e7" \
    2>/dev/null || true
  gh issue create --title "$TITLE" --body-file "$BODY" --label "$LABEL"
  exit 0
fi

if [ "$PREV_STATE" = "CLOSED" ]; then
  gh issue reopen "$EXISTING"
fi
gh issue edit "$EXISTING" --body-file "$BODY"
# A body edit notifies nobody. Comment once per new release rather than on
# every daily run between a release and the pin bump.
if grep -qF -- "<!-- watch-latest: $LATEST -->" <<<"$PREV_BODY"; then
  echo "Issue #$EXISTING already describes $LATEST; body refreshed, no comment."
else
  gh issue comment "$EXISTING" --body "google-antigravity **$LATEST** is out; the body above now diffs it against the pinned $PINNED.

---
_Generated by [Claude Code](https://claude.ai/code)_"
  echo "Updated issue #$EXISTING"
fi
